<?php
namespace App\Filament\Resources;
use App\Models\ProcurementVariant;
use Filament\Actions\{DeleteAction,DeleteBulkAction,EditAction}; use Filament\Forms\Components\{Select,TextInput,Toggle}; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Tables\Columns\{IconColumn,TextColumn}; use Filament\Tables\Table;
class ProcurementVariantResource extends Resource { protected static ?string $model=ProcurementVariant::class; protected static ?string $navigationLabel='Varian / Ukuran'; public static function form(Schema $s):Schema{return $s->components([Select::make('item_id')->relationship('item','name')->searchable()->preload()->required(),TextInput::make('code')->required(),TextInput::make('name')->required(),TextInput::make('value'),Toggle::make('is_active')->default(true)]);} public static function table(Table $t):Table{return $t->columns([TextColumn::make('item.name')->label('Item')->searchable(),TextColumn::make('code')->searchable(),TextColumn::make('name'),TextColumn::make('value'),IconColumn::make('is_active')->boolean()])->recordActions([EditAction::make(),DeleteAction::make()])->toolbarActions([DeleteBulkAction::make()]);} public static function getPages():array{return ['index'=>Pages\ManageProcurementVariants::route('/')];}}
